def load_model_version(self):
    model_version_file_path = os.path.join(
        self.cache_root_location, FileSystemCache.MODEL_VERSION_FILE_NAME)
    if os.path.exists(model_version_file_path):
        with open(model_version_file_path, 'r') as f:
            return f.read().strip()
    else:
        return None

def save_model_version(self, revision_info: Dict):
    model_version_file_path = os.path.join(
        self.cache_root_location, FileSystemCache.MODEL_VERSION_FILE_NAME)
    with open(model_version_file_path, 'w') as f:
        if isinstance(revision_info, dict):
            version_info_str = 'Revision:%s,CreatedAt:%s' % (
                revision_info['Revision'], revision_info['CreatedAt'])
            f.write(version_info_str)
        else:
            f.write(revision_info)

    # Check file integrity
    if FILE_HASH in file_meta:
        expected_hash = file_meta[FILE_HASH]
        hash_valid = True
        if file_digest is not None:
            if file_digest != expected_hash:
                logger.warning(
                    'Mismatched real-time digest for %s, falling back to full hash check',
                    file_meta['Path'])
                if not file_integrity_validation(temp_file, expected_hash):
                    hash_valid = False
        else:
            if not file_integrity_validation(temp_file, expected_hash):
                hash_valid = False

        if not hash_valid:
            if hash_attempt < HASH_RETRY_TIMES - 1:
                logger.warning(
                    'Hash validation failed for %s, '
                    'retrying download (attempt %d/%d)', file_meta['Path'],
                    hash_attempt + 1, HASH_RETRY_TIMES)
                # Clean up corrupted file before retry
                if os.path.exists(temp_file):
                    os.remove(temp_file)
                continue
            else:
                raise FileDownloadError(
                    'File %s hash validation failed after %d attempts, '
                    'the file may be corrupted.' %
                    (file_meta['Path'], HASH_RETRY_TIMES))

    # Hash validation passed or no hash to validate, exit retry loop
    break

# Put file into cache
return cache.put_file(file_meta, temp_file)
